  filter_ =
      std::make_shared<SegmentIndexFilter>(delete_store_, shared_from_this());

  // load persist forward blocks
  auto s = load_persist_scalar_blocks();
  CHECK_RETURN_STATUS(s);

  // load scalar indexes
  s = load_scalar_index_blocks();
  CHECK_RETURN_STATUS(s);

  // load FTS indexes
  s = open_fts_indexers(false);
  CHECK_RETURN_STATUS(s);

  // load vector indexes
